+static void radix_sort_u32(uint32_t* a, size_t n, uint32_t* buf) {
+    if (n == 0) return;
+    const size_t BITS = 8;
+    const size_t PASSES = 4;
+    const uint32_t MASK = (1U << BITS) - 1;
+    for (size_t p = 0; p < PASSES; ++p) {
+        uint32_t count[256] = {};
+        // Count occurrences using NEON when available
+#if defined(__ARM_NEON)
+        const size_t vec_align = 16 / sizeof(uint32_t);
+        size_t i = 0;
+        for (; i + vec_align <= n; i += vec_align) {
+            uint32x4_t v = vld1q_u32(a + i);
+            // Extract each 8-bit digit from the 32-bit lanes
+            uint32x4_t digit0 = vandq_u32(v, vdupq_n_u32(MASK));
+            uint32x4_t digit1 = vshrq_n_u32(vandq_u32(vshrq_n_u32(v, BITS), vdupq_n_u32(MASK));
+            uint32x4_t digit2 = vshrq_n_u32(vandq_u32(vshrq_n_u32(v, BITS*2), vdupq_n_u32(MASK));
+            uint32x4_t digit3 = vshrq_n_u32(vandq_u32(vshrq_n_u32(v, BITS*3), vdupq_n_u32(MASK));
+            // Combine four digits per lane (using interleaving)
+            uint32x4_t combined = vextq_u32(digit0, digit1, 2);
+            combined = vextq_u32(combined, digit2, 2);
+            combined = vextq_u32(combined, digit3, 2);
+            // Accumulate counts
+            for (int lane = 0; lane < 4; ++lane) {
+                uint32_t digit = vgetq_lane_u32(combined, lane);
+                count[digit]++;
+            }
+        }
+        // Process remaining elements scalar
+        for (; i < n; ++i) {
+            uint32_t digit = (a[i] >> (p * BITS)) & MASK;
+            count[digit]++;
+        }
+#else
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (a[i] >> (p * BITS)) & MASK;
+            count[digit]++;
+        }
+#endif
+        // Prefix sum
+        size_t total = 0;
+        for (int i = 0; i < 256; ++i) {
+            size_t c = count[i];
+            count[i] = total;
+            total += c;
+        }
+        // Place elements into buffer using branchless indexing
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (a[i] >> (p * BITS)) & MASK;
+            size_t pos = count[digit]++;
+            buf[pos] = a[i];
+        }
+        // Swap roles of a and buf for next pass
+        std::swap(a, buf);
+    }
+    // If the number of passes is even, the sorted array is in 'a', otherwise in 'buf'
+    if (PASSES % 2) {
+        std::memcpy(a, buf, n * sizeof(uint32_t));
+    }
